def adicao(num1: float, num2: float) -> float:
    return num1 + num2

def subtracao(num1: float, num2: float) -> float:
    return num1 - num2

def multiplicacao(num1: float, num2: float) -> float:
    return num1 * num2

def divisao(num1: float, num2: float) -> float:
    if num2 == 0:
        raise ValueError("Erro: Divisão por zero não é permitida.")
    return num1 / num2

def _validar_numero(prompt: str) -> float:
    while True:
        entrada = input(prompt)
        try:
            return float(entrada)
        except ValueError:
            print("Entrada inválida. Por favor, digite um número.")

def _validar_operacao() -> str:
    operadores_validos = ['+', '-', '*', '/']
    while True:
        operacao = input("Escolha a operação (+, -, *, /): ")
        if operacao in operadores_validos:
            return operacao
        else:
            print("Operação inválida. Por favor, escolha entre +, -, * ou /.")

def main():
    print("Bem-vindo à Calculadora Simples!")

    num1 = _validar_numero("Digite o primeiro número: ")
    num2 = _validar_numero("Digite o segundo número: ")
    operacao = _validar_operacao()

    resultado = None
    try:
        if operacao == '+':
            resultado = adicao(num1, num2)
        elif operacao == '-':
            resultado = subtracao(num1, num2)
        elif operacao == '*':
            resultado = multiplicacao(num1, num2)
        elif operacao == '/':
            resultado = divisao(num1, num2)

        print(f"O resultado de {num1} {operacao} {num2} é: {resultado}")
    except ValueError as e:
        print(e)
    except Exception:
        print("Ocorreu um erro inesperado ao calcular.")

if __name__ == "__main__":
    main()

