    return num1 * num2

def divisao(num1: float, num2: float) -> float:
    if num2 == 0:
        raise ValueError("Erro: Divisão por zero não é permitida.")
    return num1 / num2

def _validar_numero(prompt: str) -> float:
    while True:
        entrada = input(prompt)
        try:
            return float(entrada)
        except ValueError:
            print("Entrada inválida. Por favor, digite um número.")

def _validar_operacao() -> str:
    operadores_validos = ['+', '-', '*', '/']
    while True:
        operacao = input("Escolha a operação (+, -, *, /): ")
        if operacao in operadores_validos:
            return operacao
        else:
            print("Operação inválida. Por favor, escolha entre +, -, * ou /.")

def main():
