    num1 = _validar_numero("Digite o primeiro número: ")
    num2 = _validar_numero("Digite o segundo número: ")
    operacao = _validar_operacao()

    resultado = None
    try:
        if operacao == '+':
            resultado = adicao(num1, num2)
        elif operacao == '-':
            resultado = subtracao(num1, num2)
        elif operacao == '*':
            resultado = multiplicacao(num1, num2)
        elif operacao == '/':
            resultado = divisao(num1, num2)

        print(f"O resultado de {num1} {operacao} {num2} é: {resultado}")
    except ValueError as e:
        print(e)
    except Exception:
